import React from 'react';

const AdminUsers = () => {
    return (
        <div className="min-h-screen bg-gradient-to-b from-primestone-50 to-white py-8">
            <div className="max-w-7xl mx-auto px-4">
                <h1 className="text-3xl font-bold text-primestone-900 mb-8">User Management</h1>
                <div className="bg-white rounded-lg shadow p-6">
                    <p className="text-neutral-600">User management will appear here.</p>
                </div>
            </div>
        </div>
    );
};

export default AdminUsers;
